/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: readImportEmbeddedTags, isImportTagsV2, importTagsV2View, importAssetDurationEvidence
 *   Constants: IMPORT_TAG_LIMITS
 * Internal
 *   Types: Flags
 *   Functions: isRecord, flag, single, range, tagText, tagNames, tagIdentifier, storedText, storedNames,
 *              legacyText, normalizedAs, emptyIdentifiers
 *   Constants: fields, reasons, maxFlags, maxDurationMs, invisible
 * @end-catalog */

/**
 * Bounded, cleaned embedded-tag evidence; a value is kept whole or left out and flagged, never stripped or truncated.
 * Owner rules: docs/business-rules.md (Administrator Album Imports, tag-evidence bullet).
 */
import type { IAudioMetadata } from 'music-metadata';
import { embeddedDiscNumber, embeddedTrackNumber } from '../../services/audio/audioMetadataService';
import { normalizeGtin, normalizeIsrc, normalizeMusicBrainzId } from '../lookup/lookupIdentifiers';
import { legacyDurationEvidence } from '../lookup/lookupRanking';
import type { ImportEmbeddedTagsV2, ImportTagField, ImportTagFlag, ImportTagIdentifiers, ImportTagsView } from './adminImportContract';
import type { ImportAsset } from './adminImportMediaTypes';

/** Per-value bounds after NFC and trimming; `names` bounds each artist list. */
export const IMPORT_TAG_LIMITS = Object.freeze({ title: 300, album: 300, name: 200, catalogNumber: 100, names: 10 });
const fields: readonly ImportTagField[] = ['title', 'album', 'artists', 'albumArtists', 'label', 'barcode', 'catalogNumber', 'isrc', 'musicBrainzReleaseId'];
const reasons: readonly ImportTagFlag['reason'][] = ['characters', 'length', 'format'];
const maxFlags = fields.length * reasons.length;
const maxDurationMs = 86_400_000;
const invisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;

type Flags = ImportTagFlag[];
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
/** Each field and reason is flagged at most once. */
const flag = (flags: Flags, field: ImportTagField, reason: ImportTagFlag['reason']) => {
    if (!flags.some(item => item.field === field && item.reason === reason)) flags.push({ field, reason });
};
/**
 * The one value of a tag that may repeat (label, catalogue number, ISRC). Several distinct values are left out and flagged as
 * `format`, never cut to the first, so a co-released file names no label rather than one of two.
 */
function single(value: unknown, field: ImportTagField, flags: Flags): unknown {
    if (!Array.isArray(value)) return value;
    const distinct = new Set(value.filter((item): item is string => typeof item === 'string' && item.length <= 4_096).map(item => item.normalize('NFC').trim()).filter(Boolean));
    if (distinct.size > 1) { flag(flags, field, 'format'); return null; }
    return value.find(item => typeof item === 'string');
}
const range = (value: unknown, max: number): number | null => Number.isSafeInteger(value) && (value as number) >= 1 && (value as number) <= max ? value as number : null;

/** NFC and trimmed text of at most `max` code units without control, invisible formatting or lone surrogate characters, else null. */
function tagText(raw: unknown, max: number, field: ImportTagField, flags: Flags): string | null {
    if (typeof raw !== 'string') return null;
    // A pathological value is refused before any regular-expression work on it.
    if (raw.length > 4 * max + 64) { flag(flags, field, 'length'); return null; }
    const text = raw.normalize('NFC').trim();
    if (!text) return null;
    if (invisible.test(text)) { flag(flags, field, 'characters'); return null; }
    if (text.length > max) { flag(flags, field, 'length'); return null; }
    return text;
}
/**
 * At most 10 names, each cleaned; an invalid one is left out and flagged, and a repeated one is kept once. A list of more than 10
 * distinct names is over its limit: it is left out whole and flagged as `length`, never cut to its first names.
 */
function tagNames(raw: unknown, field: 'artists' | 'albumArtists', flags: Flags): string[] {
    const names: string[] = [], values = Array.isArray(raw) ? raw : [];
    if (new Set(values.filter(value => typeof value === 'string')).size > IMPORT_TAG_LIMITS.names) { flag(flags, field, 'length'); return names; }
    for (const value of values) {
        const name = tagText(value, IMPORT_TAG_LIMITS.name, field, flags);
        if (name && !names.includes(name)) names.push(name);
    }
    return names;
}
/** An identifier kept in its normalized form; a present value that fails its format is flagged. */
function tagIdentifier(raw: unknown, normalize: (value: string) => string | null, field: ImportTagField, flags: Flags): string | null {
    if (typeof raw !== 'string' || !raw.trim()) return null;
    const value = raw.length <= 256 ? normalize(raw.trim()) : null;
    if (!value) flag(flags, field, 'format');
    return value;
}

/**
 * Reads the version-2 evidence of one parsed audio file. Total: an unexpected or hostile tag yields an empty value (flagged where
 * it was present), never an error, so tags can never refuse otherwise valid audio.
 */
export function readImportEmbeddedTags(metadata: Pick<IAudioMetadata, 'common' | 'format'>): ImportEmbeddedTagsV2 {
    const flags: Flags = [], common = (isRecord(metadata?.common) ? metadata.common : {}) as Partial<IAudioMetadata['common']>;
    const seconds = metadata?.format?.duration, durationMs = typeof seconds === 'number' && Number.isFinite(seconds) ? Math.round(seconds * 1000) : null;
    const identifiers: ImportTagIdentifiers = {
        barcode: tagIdentifier(common.barcode, value => normalizeGtin(value)?.digits ?? null, 'barcode', flags),
        catalogNumber: tagText(single(common.catalognumber, 'catalogNumber', flags), IMPORT_TAG_LIMITS.catalogNumber, 'catalogNumber', flags),
        isrc: tagIdentifier(single(common.isrc, 'isrc', flags), normalizeIsrc, 'isrc', flags),
        musicBrainzReleaseId: tagIdentifier(common.musicbrainz_albumid, normalizeMusicBrainzId, 'musicBrainzReleaseId', flags)
    };
    return {
        version: 2,
        title: tagText(common.title, IMPORT_TAG_LIMITS.title, 'title', flags),
        album: tagText(common.album, IMPORT_TAG_LIMITS.album, 'album', flags),
        artists: tagNames(common.artists ?? [common.artist], 'artists', flags),
        albumArtists: tagNames(common.albumartists ?? [common.albumartist], 'albumArtists', flags),
        label: tagText(single(common.label, 'label', flags), IMPORT_TAG_LIMITS.name, 'label', flags),
        year: range(common.year, 9999),
        discNumber: embeddedDiscNumber(common.disk?.no) ?? null,
        trackNumber: embeddedTrackNumber(common.track?.no) ?? null,
        durationMs: durationMs !== null && durationMs >= 1 && durationMs <= maxDurationMs ? durationMs : null,
        identifiers, flagged: flags.slice(0, maxFlags)
    };
}

// Stored values are re-checked on every read; a value that fails becomes empty and is never truncated.
const storedText = (value: unknown, max: number) => typeof value === 'string' && value.length >= 1 && value.length <= max && value.trim() === value && !invisible.test(value) ? value : null;
const storedNames = (value: unknown, max: number) => [...new Set((Array.isArray(value) ? value : []).map(name => storedText(name, IMPORT_TAG_LIMITS.name)).filter((name): name is string => name !== null))].slice(0, max);
/** Version-1 evidence was only stripped of C0/C1 controls and cut to 200 characters, so it is read as the v1 DTO reads it. */
const legacyText = (value: unknown, max: number) => typeof value === 'string' && value.length <= max ? value : null;
const normalizedAs = (value: unknown, normalize: (value: string) => string | null) => typeof value === 'string' && value.length <= 64 && normalize(value) === value ? value : null;
const emptyIdentifiers = (): ImportTagIdentifiers => ({ barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null });

/** Version-2 evidence (written by uploads admitted since imports prefill from file tags); automation reads no other evidence. */
export const isImportTagsV2 = (raw: unknown): raw is ImportEmbeddedTagsV2 => isRecord(raw) && raw.version === 2 && Array.isArray(raw.artists)
    && Array.isArray(raw.albumArtists) && isRecord(raw.identifiers) && Array.isArray(raw.flagged);

/**
 * The editor's allowlisted tag view. Older evidence (no `version: 2`) reads as version 1 with its five v1 fields and
 * empty extended fields, so values it never read are not invented; version-2 evidence is checked field by field. Total; unknown
 * keys are dropped.
 */
export function importTagsV2View(raw: unknown): ImportTagsView | null {
    if (!isRecord(raw)) return null;
    const positions = { year: range(raw.year, 9999), trackNumber: range(raw.trackNumber, 9999) };
    if (!isImportTagsV2(raw)) return { version: 1, title: legacyText(raw.title, IMPORT_TAG_LIMITS.title), album: legacyText(raw.album, IMPORT_TAG_LIMITS.album), ...positions,
        artists: (Array.isArray(raw.artists) ? raw.artists : []).filter((name): name is string => legacyText(name, IMPORT_TAG_LIMITS.name) !== null).slice(0, 50),
        albumArtists: [], label: null, discNumber: null, durationMs: null, identifiers: emptyIdentifiers(), flagged: [] };
    const base = { title: storedText(raw.title, IMPORT_TAG_LIMITS.title), album: storedText(raw.album, IMPORT_TAG_LIMITS.album), ...positions };
    const ids: Record<string, unknown> = raw.identifiers, flagged: ImportTagFlag[] = [];
    for (const item of raw.flagged) if (isRecord(item) && fields.includes(item.field as ImportTagField) && reasons.includes(item.reason as ImportTagFlag['reason']) && flagged.length < maxFlags) flag(flagged, item.field as ImportTagField, item.reason as ImportTagFlag['reason']);
    return {
        version: 2, ...base, artists: storedNames(raw.artists, IMPORT_TAG_LIMITS.names), albumArtists: storedNames(raw.albumArtists, IMPORT_TAG_LIMITS.names),
        label: storedText(raw.label, IMPORT_TAG_LIMITS.name), discNumber: range(raw.discNumber, 999), durationMs: range(raw.durationMs, maxDurationMs),
        identifiers: { barcode: normalizedAs(ids.barcode, value => normalizeGtin(value)?.digits ?? null), catalogNumber: storedText(ids.catalogNumber, IMPORT_TAG_LIMITS.catalogNumber),
            isrc: normalizedAs(ids.isrc, normalizeIsrc), musicBrainzReleaseId: normalizedAs(ids.musicBrainzReleaseId, normalizeMusicBrainzId) },
        flagged
    };
}

/**
 * A staged file's known duration for metadata lookup matching: version-2 evidence is exact to the millisecond; otherwise the stored
 * `mm:ss` duration counts with 1-second precision (owner default). Null when neither is known.
 */
export function importAssetDurationEvidence(asset: Pick<ImportAsset, 'tags' | 'duration'>): { durationMs: number; durationPrecisionMs: 0 | 1000 } | null {
    const tags = importTagsV2View(asset.tags);
    if (tags?.version === 2 && tags.durationMs !== null) return { durationMs: tags.durationMs, durationPrecisionMs: 0 };
    return legacyDurationEvidence(asset.duration);
}
